class Solution {public double minTime(int n,int k,int m,int[] time,double[] mul){if(k==1&&n>1)return -1;int N=1<<n,full=N-1;int[] max=new int[N],count=new int[N];for(int mask=1;mask<N;mask++){int bit=Integer.numberOfTrailingZeros(mask),rest=mask&(mask-1);max[mask]=Math.max(max[rest],time[bit]);count[mask]=count[rest]+1;}double[] dist=new double[N*2*m];java.util.Arrays.fill(dist,Double.POSITIVE_INFINITY);dist[0]=0;java.util.PriorityQueue<double[]> q=new java.util.PriorityQueue<>((a,b)->Double.compare(a[0],b[0]));q.add(new double[]{0,0});while(!q.isEmpty()){double[] cur=q.poll();int id=(int)cur[1],stage=id%m,z=id/m,side=z%2,mask=z/2;if(cur[0]>dist[id]+1e-9)continue;if(mask==full)return cur[0];if(side==0){int remaining=full^mask;for(int sub=remaining;sub!=0;sub=(sub-1)&remaining)if(count[sub]<=k){double cost=max[sub]*mul[stage];int nextStage=(stage+(int)Math.floor(cost+1e-9))%m,next=((mask|sub)*2+1)*m+nextStage;double nd=cur[0]+cost;if(nd+1e-9<dist[next]){dist[next]=nd;q.add(new double[]{nd,next});}}}else for(int bits=mask;bits!=0;bits&=bits-1){int person=Integer.numberOfTrailingZeros(bits);double cost=time[person]*mul[stage];int nextStage=(stage+(int)Math.floor(cost+1e-9))%m,next=((mask^(1<<person))*2)*m+nextStage;double nd=cur[0]+cost;if(nd+1e-9<dist[next]){dist[next]=nd;q.add(new double[]{nd,next});}}}return -1;}}